def ie_eoq(demand=None, order_cost=None, holding_cost=None):
    """Economic order quantity (EOQ). The order quantity that minimises annual ordering plus holding cost for constant demand: Q* = sqrt(2DS/H).
    Formula: Q^* = \\sqrt{\\frac{2DS}{H}},\\quad TC^* = \\sqrt{2DSH}
    Inputs:
        demand: demand per year (units)
        order_cost: fixed cost per order or setup
        holding_cost: holding cost per unit per year
    Outputs: Q (economic order quantity Q*), orders_per_year (orders per year D/Q*), cycle_time (time between orders Q*/D (years)), ordering_cost (annual ordering cost DS/Q*), holding_cost_per_year (annual holding cost HQ*/2), total_cost (annual ordering plus holding cost)
    See also: help("ie_eoq")
    """
    given = {k: v for k, v in dict(demand=demand, order_cost=order_cost, holding_cost=holding_cost).items() if v is not None}
    return _P.solve("ie_eoq", **given)

